use std::cell::RefCell;
use std::rc::Rc;

fn main() {
    let a = Rc::new(RefCell::new(0));
    let w = Rc::downgrade(&a);
    let b = Rc::clone(&a);
    *b.borrow_mut() += 5;
    drop(a);
    let up = w.upgrade();
    println!("{} {}", up.is_some(), Rc::strong_count(&b));
}
